machine_start_gcode:
G28 ; home all axes
{if is_extruder_used[0] && !is_extruder_used[1]}G1 X330 Y0 Z50 F3600 ; park right side for heating{endif}
{if is_extruder_used[1] && !is_extruder_used[0]}G1 X0 Y0 Z50 F3600 ; park left side for heating{endif}
{if is_extruder_used[0] && is_extruder_used[1]}G1 X0 Y0 Z50 F3600 ; park for dual extruder heating{endif}
M141 S{overall_chamber_temperature} ; set heated chamber temperature
M140 S{bed_temperature_initial_layer_single} ; set build platform temperature
M190 S{bed_temperature_initial_layer_single} ; stabilize build platform temperature
{if overall_chamber_temperature > 0}M191 S{overall_chamber_temperature} ; wait for chamber temperature{endif}
{if is_extruder_used[0] && is_extruder_used[1]}M104 S{nozzle_temperature_initial_layer[1]} T1 ; set left extruder temperature
M104 S{nozzle_temperature_initial_layer[0]} T0 ; set right extruder temperature
M109 S{nozzle_temperature_initial_layer[1]} T1 ; stabilize left extruder temperature
M109 S{nozzle_temperature_initial_layer[0]} T0 ; stabilize right extruder temperature{endif}
{if is_extruder_used[0] && !is_extruder_used[1]}M104 S{nozzle_temperature_initial_layer[0]} T0 ; set right extruder temperature
M109 S{nozzle_temperature_initial_layer[0]} T0 ; stabilize right extruder temperature{endif}
{if !is_extruder_used[0] && is_extruder_used[1]}M104 S{nozzle_temperature_initial_layer[1]} T1 ; set left extruder temperature
M109 S{nozzle_temperature_initial_layer[1]} T1 ; stabilize left extruder temperature{endif}

toolchange_gcode:
{if next_extruder == 0}G1 X330 F{travel_speed * 60}{endif}
{if next_extruder == 1}G1 X0 F{travel_speed * 60}{endif}
T{next_extruder}
